// GÖMÜLÜ KAŞELER
//
// TMGD kaşeleri belge PDF'lerine basılmak üzere base64 (PNG, şeffaf zeminli)
// olarak burada saklanır. Böylece her belge üretiminde elle dosya yüklemeye
// gerek kalmaz; Belge Oluştur ekranındaki "Kaşe/imza ekle" kutusu
// işaretlendiğinde bu görseller kullanılır.
//
// Görseller kaşelerin gerçek basımlarından üretildi: eğim düzeltildi, kağıt
// zemini şeffaflaştırıldı, mürekkep tek renge sabitlendi. 360 piksel
// yükseklik, belgede basıldıkları ~15 mm ölçüde yaklaşık 600 dpi'ye karşılık
// gelir; alfa 16 kademeye yuvarlanarak dosya boyutu küçültülmüştür.

export type GomuluKase = {
  /** jsPDF'in addImage'ine verilen data URL. */
  data: string;
  /** Genişlik / yükseklik — kutuya oranı bozulmadan sığdırmak için. */
  enBoyOrani: number;
  fmt: "PNG";
  /**
   * Kaşenin belgede basılacağı GERÇEK genişlik (mm). Kaşenin fiziksel
   * boyutuyla aynı ölçüde çıkması için kullanılır. Verilmezse kaşe,
   * imza boşluğuna sığdığı kadar büyük basılır.
   */
  hedefGenislikMm?: number;
};

