/**
 * HAZIRLAYAN kutusuna basılacak kaşeyi ada göre bulur.
 * Kaşesi tanımlı olmayan bir TMGD için undefined döner — o durumda kutu
 * yalnızca isim/unvan ile basılır, hatalı bir kaşe basılmaz.
 */
/**
 * KONTROL EDEN kutusuna basılacak kaşe (TMGD Koordinatörü).
 * imzali=true ise ıslak imzalı sürüm döner.
 */
export function kontrolEdenKasesi(imzali = false): GomuluKase {
  return imzali ? KASE_YAKUP_ATAS_IMZALI : KASE_YAKUP_ATAS;
}

export function hazirlayanKasesi(
  ad: string,
  imzali = false
): GomuluKase | undefined {
  // Ad, Türkçe karakterler ASCII karşılıklarına indirgenerek karşılaştırılır:
  // aynı kişi kayıtlarda "Maşallah TEKİNOK" / "MASALLAH TEKINOK" gibi farklı
  // yazılmış olabilir; bu normalize etme sayesinde ikisi de eşleşir.
  const sade = ad
    .toLocaleUpperCase("tr")
    .replace(/[ÇĞİIÖŞÜ]/g, (c) => ({ Ç: "C", Ğ: "G", İ: "I", I: "I", Ö: "O", Ş: "S", Ü: "U" })[c] ?? c)
    .replace(/[^A-Z]/g, "");

  if (sade.includes("UMUTKILIN")) return KASE_UMUT_KILINC;
  if (sade.includes("TEKINOK")) {
    return imzali ? KASE_MASALLAH_TEKINOK_IMZALI : KASE_MASALLAH_TEKINOK;
  }
  return undefined;
}
